// Floor Plan Data — centralized model data for dynamic /floor-plans/[slug] pages
// Source: Champion Homes Box shared folders (2026 Aspire line, Topeka IN factory)

export interface FloorPlan {
  slug: string;
  name: string;
  series: string;
  type: "Single Wide" | "Double Wide" | "Modular";
  code: "HUD" | "IRC";
  sqft: number;
  beds: number;
  baths: number;
  sections: string;
  price: string;
  priceNumeric: string;
  sku: string;
  description: string;
  heroImage: string;
  heroImageAlt: string;
  galleryImages?: string[];
  pdfUrl?: string;
  features: string[];
  specs: Record<string, string>;
  faqs: Array<{ question: string; answer: string }>;
}

// Generate standard FAQs for a floor plan
function generateFAQs(plan: {
  name: string; type: string; sqft: number; beds: number; baths: number; price: string; code: string;
}): Array<{ question: string; answer: string }> {
  const isModular = plan.code === "IRC";
  const isSingle = plan.type === "Single Wide";
  const financing = isModular
    ? "Because it's built to IRC code and placed on a permanent foundation, it qualifies for conventional mortgages, FHA, VA, and USDA loans — giving you access to the lowest rates available."
    : isSingle
    ? "Chattel loans, FHA Title I, and VA loans are all options. If placed on a permanent foundation with owned land, conventional mortgages and FHA Title II loans become available too."
    : "Chattel loans from 21st Mortgage or Triad Financial are available for homes on leased land. On a permanent foundation with owned land, FHA, VA, USDA, and conventional mortgages all apply.";

  return [
    {
      question: `How much does the ${plan.name} cost?`,
      answer: `The ${plan.name} starts at ${plan.price} for the base home from the factory. Your total investment depends on delivery distance, site preparation, foundation type, and utility connections. At Factory Direct Homes Center, you get factory-direct pricing with full line-item transparency — no dealership markup, no hidden fees. You see exactly what every component costs.`,
    },
    {
      question: `What financing options are available for the ${plan.name}?`,
      answer: `${financing} Our team connects you with the right lender for your situation. Monthly payments vary by loan type, down payment, and credit score. Pre-qualification is free and doesn't affect your credit.`,
    },
    {
      question: `Can I customize the ${plan.name}?`,
      answer: `Yes, every Champion home is fully customizable. Choose your flooring, cabinetry, countertops, appliance packages, exterior colors, and interior finishes. Visit our Auburn showroom to see material samples and walk through similar models. Our team helps you personalize your home to match your style and budget.`,
    },
    {
      question: `How long does it take to get the ${plan.name}?`,
      answer: `From order to delivery, expect ${isSingle ? "8 to 12" : "10 to 16"} weeks. Factory build time at Champion's Topeka, IN facility is ${isSingle ? "4 to 6" : "6 to 8"} weeks. Site preparation should happen during the build to stay on schedule. You choose your own licensed contractor for setup — giving you control over costs and quality.`,
    },
    {
      question: `Who handles setup and installation of the ${plan.name}?`,
      answer: `At Factory Direct Homes Center, you choose your own licensed and insured contractor for setup and installation. This is a key benefit of buying factory-direct — no middleman markup on installation. You control the process, choose contractors you trust, and save money compared to dealers who bundle setup at inflated prices.`,
    },
  ];
}

