// =====================================================
// COMBINE ALL FLOOR PLANS + GENERATE FAQs
// =====================================================

export const floorPlans: FloorPlan[] = [
  ...singleWide14,
  ...singleWide16,
  ...singleWide18,
  ...doubleWide24,
  ...doubleWide28,
  ...doubleWide32,
].map((plan) => ({
  ...plan,
  faqs: plan.faqs.length > 0 ? plan.faqs : generateFAQs(plan),
}));

// Get a floor plan by slug
export function getFloorPlanBySlug(slug: string): FloorPlan | undefined {
  return floorPlans.find((p) => p.slug === slug);
}

// Get all floor plan slugs (for generateStaticParams)
export function getAllFloorPlanSlugs(): string[] {
  return floorPlans.map((p) => p.slug);
}

// Get related floor plans (same type + similar size, excluding current)
export function getRelatedFloorPlans(slug: string, count = 3): FloorPlan[] {
  const current = floorPlans.find((p) => p.slug === slug);
  if (!current) return floorPlans.slice(0, count);
  return floorPlans
    .filter((p) => p.slug !== slug)
    .sort((a, b) => {
      const aTypeMatch = a.type === current.type ? 2 : 0;
      const bTypeMatch = b.type === current.type ? 2 : 0;
      const aSizeDiff = Math.abs(a.sqft - current.sqft);
      const bSizeDiff = Math.abs(b.sqft - current.sqft);
      return (bTypeMatch - aTypeMatch) || (aSizeDiff - bSizeDiff);
    })
    .slice(0, count);
}
